  faq_q1: 'Homatch, kamuya açık ilan olmadan alıcıları nasıl buluyor?',
  faq_a1: 'Homatch, Facebook grupları, Telegram süpergrupları, forumlar, Google ve Bing gibi kamuya açık kanalları satın alma veya kiralama niyeti içeren gönderiler için tarar. Bu sinyalleri mülk özelliklerinizle eşleştirir.',
