  hero_step4_desc: 'שלם לפי תוצאה. כל קרדיט פותח אות של קונה, שוכר או משקיע מוסמך.',
  hero_private_bullet3: 'בשימוש מוכרים שרוצים שיקול דעת לפני כניסה לשוק.',
  hero_faq_headline: 'שאלות נפוצות',
  faq_q1: 'איך Homatch מוצא קונים ללא מודעה ציבורית?',
  faq_a1: 'Homatch סורק ערוצים ציבוריים — קבוצות Facebook, סופרגרופים בטלגרם, פורומים, Google וBing — לפוסטים שמביעים כוונת קנייה או שכירה. אנו מתאימים את האותות לפרטי הנכס שלך.',
  faq_q2: 'האם הנכס שלי גלוי לציבור?',
  faq_a2: 'לא. מודעות פרטיות לעולם אינן מפורסמות. הכתובת, המחיר והתמונות מוסתרים עד שתבחר לפתוח התאמה.',
  faq_q3: 'מה מתגלה לאחר פתיחת התאמה?',
  faq_a3: 'לאחר הפתיחה תראה את הטקסט המלא של האות המקורי, הפלטפורמה והקבוצה, קישור ישיר לפוסט או לפרופיל, ופרטי הכוונה שחולצו על ידי AI כולל תקציב, מיקום וסוג נכס.',
  faq_q4: 'מה אם לא נמצאות התאמות?',
  faq_a4: 'קרדיטים מנוכים רק כשפותחים התאמה. אם אין התאמות — לא מנוכה דבר. ניתן להשהות או למחוק את הקמפיין בכל עת.',
  faq_q5: 'אילו שווקי נדל"ן Homatch תומך בהם?',
  faq_a5: 'Homatch מותאם כיום לגאורגיה (טביליסי וערים גדולות). שווקים נוספים בתכנון.',
